def read(p):
 with open(os.path.join(root,p),'rb') as f:return f.read().decode('utf-8')
def method(source,signature):
 a=source.index(signature);b=source.find('\n- (',a+1);c=source.find('\n+ (',a+1);end=min([x for x in [b,c,source.find('\n@end',a)] if x>=0]);return source[a:end]
