def cls(name,specs,body):
 ivars=''.join(t+' _'+n+';' for t,n in specs);props=''.join('@property(nonatomic,'+('retain' if '*' in t else 'assign')+') '+t+' '+n+';' for t,n in specs);synth=''.join('@synthesize '+n+'=_'+n+';' for t,n in specs);release=''.join('[_'+n+' release];' for t,n in specs if '*' in t)
 return '@interface '+name+':NSWindowController<NSTableViewDataSource>{'+ivars+'}'+props+'@end\n@implementation '+name+'\n'+synth+'\n'+body+'\n- (void)dealloc{[[self window] setDelegate:nil];'+release+'[super dealloc];}\n@end\n'
